  _nextWave() {
    this.wave++;
    if (this.wave > CONFIG.waves.length) {
      this._endRun(true);
      return;
    }
    const def = CONFIG.waves[this.wave - 1];
    this.hud.toast(`回合 ${this.wave}：${def.count} 名敌人`);
    this.audio.wave(this.wave);

    // 生成敌人队列（从出生点随机分配）
    const names = ['Phantom', 'Viper', 'Ghost', 'Reaper', 'Fang', 'Echo', 'Talon', 'Raven'];
    this.spawnQueue = [];
    for (let i = 0; i < def.count; i++) {
      const spawn = this.gameMap.spawns.enemy[i % this.gameMap.spawns.enemy.length];
      this.spawnQueue.push({
        pos: spawn.clone().add(new THREE.Vector3(
          (Math.random() - 0.5) * 4, 0, (Math.random() - 0.5) * 4
        )),
        hp: def.hp,
        speed: def.speed,
        name: names[Math.floor(Math.random() * names.length)],
      });
    }
    // 立即刷出前 2 个，其余间隔刷
    this._spawnFromQueue(2);
    this.spawnTimer = 2.5;
    this._refreshScore();
  }

  _spawnFromQueue(n) {
    for (let i = 0; i < n && this.spawnQueue.length > 0; i++) {
      const spec = this.spawnQueue.shift();
      const en = new Enemy(this.scene, this.gameMap, this.player, this.hud, {
        hp: spec.hp, speed: spec.speed, name: spec.name,
      });
      en.spawnAt(spec.pos);
      this.enemies.push(en);
    }
    this._refreshScore();
  }

  _refreshScore() {
    const alive = this.enemies.filter(e => e.alive).length + this.spawnQueue.length;
    this.hud.updateScore(alive, this.kills, this.wave);
  }

